import { CapabilityRegistry } from './capability-registry.js';
const $=id=>document.getElementById(id);let active='live',page=0,registry=null;
const tabs=[...document.querySelectorAll('[data-panel]')];
for(const b of tabs)b.addEventListener('click',()=>{active=b.dataset.panel;for(const x of tabs){const on=x===b;x.setAttribute('aria-selected',String(on));$('panel-'+x.dataset.panel).hidden=!on;}if(active==='inventory')draw();});
function el(tag,text,cls){const x=document.createElement(tag);x.textContent=text;if(cls)x.className=cls;return x;}
function draw(){if(!registry){$('cap-count').textContent='Loading source inventory and existing swarm…';return;}const m=registry.summary();$('cap-metrics').replaceChildren(...[['Harvested',m.harvested],['Observed',m.observed],['Earned',m.earned],['Job signatures',m.signatures],['Builder parts',m.tools],['Original files',m.files]].map(([name,val])=>{const d=el('div','');d.append(el('strong',val.toLocaleString()),el('small',name));return d;}));const rows=registry.search($('cap-search').value,$('cap-kind').value),size=18,max=Math.max(0,Math.ceil(rows.length/size)-1);page=Math.max(0,Math.min(page,max));$('cap-count').textContent=`${rows.length.toLocaleString()} matching entries`;const items=rows.slice(page*size,(page+1)*size).map(x=>{const d=el('article','','cap-entry');d.append(el('strong',x.name),el('span',x.status,'cap-state'),el('p',x.detail),el('p',x.source));return d;});$('cap-results').replaceChildren(...items);$('cap-page').textContent=`${page+1} / ${max+1}`;$('cap-prev').disabled=page===0;$('cap-next').disabled=page===max;}
$('cap-search').addEventListener('input',()=>{page=0;draw();});$('cap-kind').addEventListener('change',()=>{page=0;draw();});$('cap-prev').onclick=()=>{page--;draw();};$('cap-next').onclick=()=>{page++;draw();};
try{const r=await fetch('./capability-index.json');if(!r.ok)throw Error('Source inventory unavailable');const index=await r.json();registry=new CapabilityRegistry(null,index);window.__capabilities=registry;const attach=()=>{if(window.__FA)registry.faces=window.__FA;if(window.__S&&!Object.hasOwn(window.__S,'capabilities'))Object.defineProperty(window.__S,'capabilities',{value:registry,enumerable:false});if(active==='inventory'&&document.activeElement!==$('cap-search'))draw();};attach();setInterval(attach,2500);}catch(e){$('cap-count').textContent=e.message;}
